"        const response = await posService.searchCustomers(customerPhone);
        if (response.data && Array.isArray(response.data)) {
          setSearchResults(response.data);
          setShowSearchResults(response.data.length > 0);
          setCustomerDb(prev => {
            const next = { ...prev };
            response.data.forEach(c => {
              if (c.number) {
                next[c.number] = {
                  name: c.name || '',
                  phone: c.number,
                  address: c.address || '',
                  points: Number(c.points) || 0,
                  balance: Number(c.balance) || 0,
                  orders: Number(c.orders) || prev[c.number]?.orders || 0,
                  totalSpent: Number(c.total_spent || c.totalSpent) || prev[c.number]?.totalSpent || 0
                };
              }
            });
            localStorage.setItem('pos_customer_db', JSON.stringify(next));
            return next;
          });
        }"

